import sys

def MEX(s):
    mex = 0
    while mex in s:
        mex += 1
    return mex

def construct_array(n, a):
    b = []
    used = set()

    for i in range(n):
        if a[i] > i + 1:
            return "-1"

        # Add the current MEX to the set of used numbers
        used.add(MEX(used))

        # Ensure the MEX of the current prefix is a[i]
        while MEX(used) != a[i]:
            used.add(MEX(used))

        # The last added number is the current MEX
        b.append(MEX(used) - 1)

    return " ".join(map(str, b))

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = construct_array(n, a)
    print(result)

if __name__ == "__main__":
    main()
